<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
(function () {
'use strict';

/* ============================================================
   Deterministic PRNG — Mulberry32, fixed seed 42.
   Every procedural choice (geometry jitter, particle initial
   states, sheet placement) is drawn from this stream at init.
   The simulation itself is a pure parametric function of
   simTime, so scrubbing / reset / replay are frame-exact.
   ============================================================ */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rng = mulberry32(42);
const rand = (a, b) => a + (b - a) * rng();
const TAU = Math.PI * 2;

const DURATION = 8.000;

/* ============================================================
   Renderer / scene / camera
   ============================================================ */
const canvas = document.getElementById('stage');
const renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.setSize(window.innerWidth, window.innerHeight, false);
renderer.setClearColor(0x000000, 0);
renderer.outputEncoding = THREE.sRGBEncoding;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(35, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 0.32, 11.6);
camera.lookAt(0, 0.12, 0);

/* ============================================================
   Procedural studio environment (PMREM from an in-memory
   light-box scene — no external assets).
   ============================================================ */
(function buildEnvironment() {
  const envScene = new THREE.Scene();
  envScene.background = new THREE.Color(0x05060a);
  const mk = (w, h, rgb, pos) => {
    const m = new THREE.Mesh(
      new THREE.PlaneGeometry(w, h),
      new THREE.MeshBasicMaterial({ color: new THREE.Color().setRGB(rgb[0], rgb[1], rgb[2]), side: THREE.DoubleSide })
    );
    m.position.set(pos[0], pos[1], pos[2]);
    m.lookAt(0, 0, 0);
    envScene.add(m);
  };
  mk(7, 5, [3.2, 3.0, 2.7], [5, 7, 5]);      // warm key softbox
  mk(5, 8, [0.5, 2.4, 3.2], [-7, 2, -3]);    // cyan rim strip
  mk(6, 4, [2.4, 0.6, 2.0], [5, -4, -6]);    // magenta rim strip
  mk(9, 9, [1.1, 1.15, 1.3], [0, 9, -1]);    // top wash
  mk(10, 3, [0.25, 0.28, 0.34], [0, -8, 2]); // floor bounce
  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(envScene, 0.06).texture;
  pmrem.dispose();
})();

/* ============================================================
   Three-point studio lighting (also fed to custom shaders)
   ============================================================ */
const keyLight = new THREE.DirectionalLight(0xfff2e0, 1.15);
keyLight.position.set(4, 6, 6);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0x8fa3c8, 0.4);
fillLight.position.set(-6, 2.5, 4);
scene.add(fillLight);
const rimCool = new THREE.DirectionalLight(0xe8f6ff, 1.7);
rimCool.position.set(-4, 3.5, -6);
scene.add(rimCool);
const rimCyan = new THREE.DirectionalLight(0x66e0ff, 1.1);
rimCyan.position.set(2, 4, -6);
scene.add(rimCyan);
const rimMagenta = new THREE.DirectionalLight(0xd060e8, 0.85);
rimMagenta.position.set(5, -1.5, -5.5);
scene.add(rimMagenta);
scene.add(new THREE.AmbientLight(0x1c2028, 0.5));

const flashEntry = new THREE.PointLight(0xffd9a0, 0, 9, 2);
flashEntry.position.set(0.9, 0.18, 0.7);
scene.add(flashEntry);
const flashExit = new THREE.PointLight(0xcfe8ff, 0, 9, 2);
flashExit.position.set(-0.9, 0.12, 0.7);
scene.add(flashExit);

/* ============================================================
   Shared GLSL helpers (deterministic hash noise)
   ============================================================ */
const GLSL_NOISE = `
float hash13(vec3 p3){
  p3 = fract(p3 * 0.1031);
  p3 += dot(p3, p3.zyx + 31.32);
  return fract((p3.x + p3.y) * p3.z);
}
float noise3(vec3 p){
  vec3 i = floor(p); vec3 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash13(i);
  float b = hash13(i + vec3(1.0, 0.0, 0.0));
  float c = hash13(i + vec3(0.0, 1.0, 0.0));
  float d = hash13(i + vec3(1.0, 1.0, 0.0));
  float e = hash13(i + vec3(0.0, 0.0, 1.0));
  float g = hash13(i + vec3(1.0, 0.0, 1.0));
  float h = hash13(i + vec3(0.0, 1.0, 1.0));
  float k = hash13(i + vec3(1.0, 1.0, 1.0));
  return mix(mix(mix(a, b, f.x), mix(c, d, f.x), f.y),
             mix(mix(e, g, f.x), mix(h, k, f.x), f.y), f.z);
}
`;

const GLSL_LIGHTS = `
const vec3 L_KEY = vec3(0.485, 0.727, 0.727);
const vec3 L_FILL = vec3(-0.802, 0.334, 0.534);
const vec3 L_RIMC = vec3(-0.470, 0.411, -0.705);
const vec3 L_RIMCY = vec3(0.267, 0.535, -0.802);
const vec3 L_RIMM = vec3(0.639, -0.192, -0.703);
`;

/* ============================================================
   Teardrop profile — hydrostatic sag (wide bottom, narrow neck)
   ============================================================ */
const profileCtrl = [
  new THREE.Vector2(0.001, -1.18),
  new THREE.Vector2(0.42, -1.10),
  new THREE.Vector2(0.72, -0.88),
  new THREE.Vector2(0.90, -0.52),
  new THREE.Vector2(0.97, -0.12),
  new THREE.Vector2(0.94, 0.28),
  new THREE.Vector2(0.80, 0.66),
  new THREE.Vector2(0.55, 0.98),
  new THREE.Vector2(0.28, 1.18),
  new THREE.Vector2(0.12, 1.30),
  new THREE.Vector2(0.075, 1.38),
  new THREE.Vector2(0.10, 1.43),
  new THREE.Vector2(0.045, 1.47),
  new THREE.Vector2(0.001, 1.48)
];
const profilePts = new THREE.SplineCurve(profileCtrl).getPoints(72);
const balloonGeo = new THREE.LatheGeometry(profilePts, 96);
const waterGeo = new THREE.LatheGeometry(profilePts, 96);
waterGeo.scale(0.965, 0.965, 0.965);

/* analytic radius approximation for volume sampling */
function teardropRadius(y) {
  const yn = (y + 0.12) / 1.27;
  if (yn <= -1 || yn >= 1) return 0;
  return 0.96 * Math.pow(1 - yn * yn, 0.62) * (1 - 0.22 * Math.pow(Math.max(yn, 0), 2.5));
}
function sampleWaterVolume(scale) {
  let y, r, rr;
  do {
    y = rand(-1.12, 1.30);
    r = teardropRadius(y);
    rr = Math.sqrt(rng()) * r;
  } while (r <= 0.01);
  const th = rng() * TAU;
  return [Math.cos(th) * rr * scale, y * scale + 0.02, Math.sin(th) * rr * scale];
}

/* ============================================================
   Latex membrane — crimson, gloss, fresnel, fake subsurface,
   elastic indentation + radiating tear with alpha discard.
   ============================================================ */
const latexUniforms = {
  uTime: { value: 0 },
  uCam: { value: camera.position.clone() },
  uColor: { value: new THREE.Color('#e61c24').convertSRGBToLinear() }
};
const latexMat = new THREE.ShaderMaterial({
  uniforms: latexUniforms,
  transparent: true,
  depthWrite: false,
  side: THREE.DoubleSide,
  vertexShader: GLSL_NOISE + `
    uniform float uTime;
    varying vec3 vN; varying vec3 vW; varying vec3 vOrig;
    varying float vTorn; varying float vAlpha;
    void main(){
      float t = uTime;
      vec3 p = position; vec3 n = normal;
      vec3 c = vec3(0.0, 0.10, 0.0);
      vec3 dir = normalize(p - c);
      vec3 impDir = normalize(vec3(1.0, 0.14, 0.0));
      float a = acos(clamp(dot(dir, impDir), -1.0, 1.0));

      // resting hydrostatic breathing
      float breathe = 0.006 * sin(t * 2.1 + p.y * 2.0) + 0.004 * sin(t * 3.7 + p.x * 4.0);
      p += n * breathe * (1.0 - smoothstep(1.0, 1.3, t));

      // elastic indentation before puncture, then damped elastic ring
      float indent = smoothstep(1.0, 1.13, t);
      float rt = max(t - 1.13, 0.0);
      float ring = exp(-rt * 5.0) * cos(rt * 20.0) * step(1.13, t);
      float dent = indent * (1.0 - smoothstep(1.13, 1.4, t)) + 0.22 * ring;
      p.x -= 0.30 * dent * exp(-pow(a / 0.55, 2.0));
      p += n * 0.07 * dent * exp(-pow((a - 0.6) / 0.22, 2.0));

      // radiating tear front (skin retracts ~5x faster than fluid)
      float jag = 0.82 + 0.36 * hash13(floor(dir * 7.0) + 17.0);
      float front = rt * 8.5 * jag;
      float k = clamp((front - a) / 0.30, 0.0, 1.0);
      k = k * k * (3.0 - 2.0 * k);
      vTorn = k;
      if (k > 0.001) {
        float upMix = smoothstep(-0.5, 0.55, position.y);
        vec3 neck = vec3(0.0, 1.36, 0.0);
        vec3 base = vec3(0.0, -1.10, 0.0);
        vec3 target = mix(base, neck, upMix);
        vec3 crum = (vec3(hash13(p * 13.1), hash13(p * 7.7 + 3.1), hash13(p * 5.3 + 9.2)) - 0.5)
                    * 0.16 * (1.0 - 0.5 * k);
        // base remnant detaches and drops after the burst
        float fallT = max(t - 2.2, 0.0);
        target.y -= 1.1 * fallT * fallT * (1.0 - upMix);
        p = mix(p, target + crum, k * 0.97);
      }
      vAlpha = 1.0 - smoothstep(0.80, 0.99, k);
      vAlpha *= 1.0 - (1.0 - smoothstep(-0.5, 0.55, position.y)) * smoothstep(2.7, 3.5, t) * 0.95;

      vOrig = position;
      vec4 w = modelMatrix * vec4(p, 1.0);
      vW = w.xyz;
      vN = normalize(mat3(modelMatrix) * n);
      gl_Position = projectionMatrix * viewMatrix * w;
    }
  `,
  fragmentShader: GLSL_NOISE + GLSL_LIGHTS + `
    uniform float uTime; uniform vec3 uCam; uniform vec3 uColor;
    varying vec3 vN; varying vec3 vW; varying vec3 vOrig;
    varying float vTorn; varying float vAlpha;
    void main(){
      if (vAlpha < 0.02) discard;
      vec3 N = normalize(vN);
      if (!gl_FrontFacing) N = -N;
      vec3 V = normalize(uCam - vW);
      float fres = pow(1.0 - max(dot(N, V), 0.0), 3.0);

      vec3 diff = vec3(0.0);
      diff += vec3(1.0, 0.96, 0.9) * 1.15 * pow(clamp(dot(N, L_KEY) * 0.5 + 0.5, 0.0, 1.0), 2.0);
      diff += vec3(0.55, 0.65, 0.8) * 0.45 * pow(clamp(dot(N, L_FILL) * 0.5 + 0.5, 0.0, 1.0), 2.0);
      vec3 col = uColor * (0.24 + diff * 0.9);

      // high-gloss latex specular
      vec3 H = normalize(L_KEY + V);
      col += vec3(1.0, 0.96, 0.9) * pow(max(dot(N, H), 0.0), 140.0) * 1.25;
      H = normalize(L_RIMC + V);
      col += vec3(0.9, 0.97, 1.0) * pow(max(dot(N, H), 0.0), 90.0) * 0.9;
      H = normalize(L_RIMCY + V);
      col += vec3(0.4, 0.9, 1.0) * pow(max(dot(N, H), 0.0), 70.0) * 0.5;

      // subtle subsurface transmission (light bleeding through latex)
      float trans = pow(clamp(dot(V, -(L_RIMC - N * 0.35)), 0.0, 1.0), 3.0);
      col += vec3(1.0, 0.18, 0.12) * trans * 0.55;
      float trans2 = pow(clamp(dot(V, -(L_KEY - N * 0.3)), 0.0, 1.0), 4.0);
      col += vec3(1.0, 0.3, 0.15) * trans2 * 0.3;

      // fresnel edge highlights
      col += mix(vec3(0.9, 0.97, 1.0), vec3(0.4, 0.9, 1.0), 0.5) * fres * 0.55;
      col += vec3(1.0, 0.9, 0.95) * fres * fres * 0.35;

      col *= 0.9 + 0.2 * noise3(vOrig * 6.0);
      float alpha = vAlpha * (0.80 + 0.15 * fres);
      gl_FragColor = vec4(col, alpha);
      #include <tonemapping_fragment>
      #include <encodings_fragment>
    }
  `
});
const latexMesh = new THREE.Mesh(balloonGeo, latexMat);
latexMesh.renderOrder = 3;
scene.add(latexMesh);

/* ============================================================
   Water mass — retains teardrop shape through inertial stasis,
   opens entry/exit wounds, then noise-driven disintegration.
   ============================================================ */
const waterUniforms = {
  uTime: { value: 0 },
  uCam: { value: camera.position.clone() }
};
const waterMat = new THREE.ShaderMaterial({
  uniforms: waterUniforms,
  transparent: true,
  depthWrite: false,
  side: THREE.DoubleSide,
  vertexShader: GLSL_NOISE + `
    uniform float uTime;
    varying vec3 vN; varying vec3 vW; varying vec3 vOrig;
    varying float vHole; varying float vDiss;
    void main(){
      float t = uTime;
      vec3 p = position; vec3 n = normal;
      vec3 c = vec3(0.0, 0.10, 0.0);
      vec3 dir = normalize(p - c);
      vec3 impDir = normalize(vec3(1.0, 0.14, 0.0));
      vec3 exitDir = normalize(vec3(-1.0, 0.06, 0.0));
      float aE = acos(clamp(dot(dir, impDir), -1.0, 1.0));
      float aX = acos(clamp(dot(dir, exitDir), -1.0, 1.0));

      // pre-shot jiggle
      float jig = (0.008 * sin(t * 2.6 + p.y * 3.1) + 0.005 * sin(t * 4.3 + p.x * 5.2))
                  * (1.0 - smoothstep(1.0, 1.4, t));
      p += n * jig;

      // impact dent + elastic overshoot
      float dent = smoothstep(1.0, 1.13, t) * (1.0 - smoothstep(1.2, 1.7, t));
      float rt = max(t - 1.13, 0.0);
      float osc = exp(-rt * 3.0) * cos(rt * 16.0) * step(1.13, t) * 0.12;
      p.x -= 0.26 * dent * exp(-pow(aE / 0.55, 2.0));
      p += n * osc * exp(-pow(aE / 0.9, 2.0));

      // travelling capillary ripple from the entry wound
      p += n * 0.02 * sin(aE * 9.0 - rt * 13.0) * exp(-rt * 1.6) * exp(-aE * 0.5);

      vec3 radial = normalize(vec3(0.0, p.y - 0.10, p.z) + vec3(0.0, 0.0001, 0.0));

      // entry wound opening (right side)
      float gateE = smoothstep(1.2, 1.35, t);
      float hE = (0.10 + 0.30 * smoothstep(1.25, 2.7, t)) * gateE;
      float lipE = (1.0 - smoothstep(hE * 0.8 + 0.001, hE * 1.8 + 0.002, aE)) * gateE;
      p += radial * lipE * 0.10;
      p.x += lipE * 0.06;
      vHole = mix(1.0, smoothstep(hE * 0.45 + 0.0005, hE * 1.05 + 0.001, aE), gateE);

      // exit wound opening (left side)
      float gateX = smoothstep(3.75, 3.9, t);
      float hX = (0.06 + 0.34 * smoothstep(3.8, 4.7, t)) * gateX;
      float lipX = (1.0 - smoothstep(hX * 0.8 + 0.001, hX * 1.8 + 0.002, aX)) * gateX;
      p += radial * lipX * 0.12;
      p.x -= lipX * 0.07;
      vHole = min(vHole, mix(1.0, smoothstep(hX * 0.45 + 0.0005, hX * 1.05 + 0.001, aX), gateX));

      // cavitation-era pressure bulge along the shot axis
      float tb2 = smoothstep(2.4, 3.0, t) * (1.0 - smoothstep(3.9, 4.5, t));
      p += n * 0.03 * tb2 * exp(-pow(abs(p.y - 0.10) / 0.5, 2.0));

      // Rayleigh-Taylor / Plateau-Rayleigh disintegration
      float tb = max(t - 5.0, 0.0);
      float n1 = noise3(p * 2.6 + 11.0);
      float n2 = noise3(p * 5.0 + 71.0);
      float amp = 0.10 * smoothstep(0.0, 0.7, tb) + 0.45 * smoothstep(0.4, 1.3, tb);
      p += n * (n1 - 0.5) * 2.0 * amp;
      p.y -= tb * tb * 0.28 * (0.4 + 0.6 * n2);
      p.x *= 1.0 + 0.22 * tb * n1;
      p.z *= 1.0 + 0.22 * tb * n2;
      vDiss = noise3(position * 3.2 + 5.0);

      vOrig = position;
      vec4 w = modelMatrix * vec4(p, 1.0);
      vW = w.xyz;
      vN = normalize(mat3(modelMatrix) * n);
      gl_Position = projectionMatrix * viewMatrix * w;
    }
  `,
  fragmentShader: GLSL_NOISE + GLSL_LIGHTS + `
    uniform float uTime; uniform vec3 uCam;
    varying vec3 vN; varying vec3 vW; varying vec3 vOrig;
    varying float vHole; varying float vDiss;
    void main(){
      float dissLevel = smoothstep(0.12, 1.28, max(uTime - 5.0, 0.0));
      if (vDiss < dissLevel) discard;
      if (vHole < 0.04) discard;
      vec3 N = normalize(vN);
      if (!gl_FrontFacing) N = -N;
      vec3 V = normalize(uCam - vW);
      float fres = pow(1.0 - max(dot(N, V), 0.0), 2.5);
      vec3 R = reflect(-V, N);

      // procedural studio reflection (analytic light-box gradient)
      vec3 env = mix(vec3(0.02, 0.03, 0.05), vec3(0.10, 0.14, 0.19), clamp(R.y * 0.5 + 0.5, 0.0, 1.0));
      env += vec3(1.0, 0.97, 0.9) * pow(max(dot(R, L_KEY), 0.0), 24.0) * 1.2;
      env += vec3(0.7, 0.9, 1.0) * pow(max(dot(R, L_RIMC), 0.0), 18.0) * 1.4;
      env += vec3(0.4, 0.9, 1.0) * pow(max(dot(R, L_RIMCY), 0.0), 22.0) * 0.9;
      env += vec3(0.9, 0.5, 1.0) * pow(max(dot(R, L_RIMM), 0.0), 20.0) * 0.8;

      vec3 body = vec3(0.30, 0.48, 0.55) * 0.35;
      float spec = pow(max(dot(N, normalize(L_KEY + V)), 0.0), 160.0) * 1.4;
      vec3 col = body + env * (0.25 + 0.75 * fres) + vec3(1.0) * spec;
      col += vec3(0.65, 0.85, 1.0) * fres * 0.5;
      col += 0.04 * noise3(vW * 8.0 + uTime * 0.7);

      // cavitation glow inside the tunnel era
      float glow = smoothstep(2.4, 2.9, uTime) * (1.0 - smoothstep(3.8, 4.4, uTime));
      col += vec3(0.5, 0.8, 1.0) * glow * 0.18 * exp(-pow((vW.y - 0.10) / 0.4, 2.0));

      float alpha = (0.30 + 0.5 * fres) * vHole;
      gl_FragColor = vec4(col, alpha);
      #include <tonemapping_fragment>
      #include <encodings_fragment>
    }
  `
});
