/* Bullet kinematics — piecewise analytic, pure function of t */
const X_START = 7.6, X_CONTACT = 0.97, T_CONTACT = 1.0, T_PUNCT = 1.13;
const V_APP = (X_START - X_CONTACT) / T_CONTACT;
const V0 = 1.5, VF = 0.55, K_DRAG = 5.0;
const T_EXIT = 3.894, X_EXIT = -0.97, V_CRUISE = 1.5, TAU_RELAX = 0.25;
function tipX(t) {
  if (t <= T_CONTACT) return X_START - V_APP * t;
  if (t <= T_PUNCT) {
    const u = (t - T_CONTACT) / (T_PUNCT - T_CONTACT);
    return X_CONTACT - 0.23 * Math.pow(u, 0.85);
  }
  if (t <= T_EXIT) {
    const ta = t - T_PUNCT;
    return 0.74 - (VF * ta + (V0 - VF) * (1 - Math.exp(-K_DRAG * ta)) / K_DRAG);
  }
  const te = t - T_EXIT;
  return X_EXIT - (V_CRUISE * te - (V_CRUISE - VF) * TAU_RELAX * (1 - Math.exp(-te / TAU_RELAX)));
}

