const shredCol = new THREE.Color();
for (let i = 0; i < 160; i++) {
  const b = rand(1.13, 1.55);
  const d = coneDir(1, 1.2);
  const sp = rand(2.5, 7.0);
  shredCol.setRGB(rand(0.75, 1.0), rand(0.08, 0.16), rand(0.1, 0.18)).convertSRGBToLinear();
  S.birth.push(b); S.life.push(rand(0.7, 1.5));
  S.p0.push(IMP[0] + d[0] * 0.05, IMP[1] + d[1] * 0.05, d[2] * 0.05);
  S.v0.push(d[0] * sp, d[1] * sp + rand(0, 0.8), d[2] * sp);
  S.size.push(rand(0.05, 0.13));
  S.color.push(shredCol.r, shredCol.g, shredCol.b);
  S.kind.push(0); S.seed.push(rng());
}
const shredGeo = new THREE.BufferGeometry();
shredGeo.setAttribute('position', new THREE.Float32BufferAttribute(new Float32Array(S.birth.length * 3), 3));
shredGeo.setAttribute('aBirth', new THREE.Float32BufferAttribute(S.birth, 1));
shredGeo.setAttribute('aLife', new THREE.Float32BufferAttribute(S.life, 1));
shredGeo.setAttribute('aP0', new THREE.Float32BufferAttribute(S.p0, 3));
shredGeo.setAttribute('aV0', new THREE.Float32BufferAttribute(S.v0, 3));
shredGeo.setAttribute('aSize', new THREE.Float32BufferAttribute(S.size, 1));
shredGeo.setAttribute('aColor', new THREE.Float32BufferAttribute(S.color, 3));
shredGeo.setAttribute('aKind', new THREE.Float32BufferAttribute(S.kind, 1));
shredGeo.setAttribute('aSeed', new THREE.Float32BufferAttribute(S.seed, 1));
shredGeo.boundingSphere = new THREE.Sphere(new THREE.Vector3(0, 0, 0), 60);
const shredUniforms = {
  uTime: { value: 0 }, uPixelScale: { value: 1 }, uMap: { value: shredTex },
  uGMult: { value: 1.5 }, uKMult: { value: 1.3 }
};
const shreds = new THREE.Points(shredGeo, new THREE.ShaderMaterial({
  uniforms: shredUniforms,
  vertexShader: PARTICLE_VERT,
  fragmentShader: PARTICLE_FRAG,
  transparent: true,
  depthWrite: false,
  blending: THREE.NormalBlending
}));
shreds.renderOrder = 7;
shreds.frustumCulled = false;
scene.add(shreds);

/* ============================================================
   Fluid sheets — curved tearing films during disintegration
   ============================================================ */
const sheetGeo = new THREE.PlaneGeometry(1, 1, 10, 10);
const sheetMats = [];
const upVec = new THREE.Vector3(0, 1, 0);
sheetDefs.forEach(function (def) {
  const dir = new THREE.Vector3(def.dir[0], def.dir[1], def.dir[2]).normalize();
  let t1 = new THREE.Vector3().crossVectors(dir, upVec);
  if (t1.lengthSq() < 0.01) t1 = new THREE.Vector3(1, 0, 0);
  t1.normalize();
  const t2 = new THREE.Vector3().crossVectors(dir, t1).normalize();
  const basis = new THREE.Matrix3().set(
    t1.x, t2.x, dir.x,
    t1.y, t2.y, dir.y,
    t1.z, t2.z, dir.z
  );
  const u = {
    uTime: { value: 0 }, uBirth: { value: def.birth }, uLife: { value: def.life },
    uSize: { value: def.size }, uSeed: { value: def.seed },
    uOrigin: { value: new THREE.Vector3(def.origin[0], def.origin[1], def.origin[2]) },
    uDir: { value: dir.clone() }, uBasis: { value: basis },
    uCam: { value: camera.position.clone() }
  };
  const mat = new THREE.ShaderMaterial({
    uniforms: u, transparent: true, depthWrite: false, side: THREE.DoubleSide,
    vertexShader: `
      uniform float uTime; uniform float uBirth; uniform float uLife; uniform float uSize; uniform float uSeed;
      uniform vec3 uOrigin; uniform vec3 uDir; uniform mat3 uBasis;
      varying vec2 vLocal; varying float vU; varying vec3 vW; varying vec3 vN;
      void main(){
        float age = uTime - uBirth;
        float alive = step(0.0, age) * step(age, uLife);
        float u = clamp(age / uLife, 0.0, 1.0);
        float s = uSize * mix(0.3, 1.65, smoothstep(0.0, 0.85, u));
        vec3 lp = position;
        lp.z = 0.20 * sin(lp.x * 3.14159) * cos(lp.y * 2.6 + uSeed) + 0.08 * sin(lp.y * 5.0 + uSeed * 2.0);
        vec3 wp = uOrigin + uBasis * (lp * s) + uDir * (0.75 * age) + vec3(0.0, -0.75 * age * age, 0.0);
        vLocal = position.xy; vU = u;
        vN = uBasis * vec3(0.0, 0.0, 1.0);
        vec4 w = modelMatrix * vec4(wp, 1.0);
        vW = w.xyz;
        gl_Position = projectionMatrix * viewMatrix * w;
        if (alive < 0.5) gl_Position = vec4(0.0, 0.0, 2.0, 1.0);
      }
    `,
    fragmentShader: GLSL_NOISE + `
      uniform float uSeed; uniform vec3 uCam;
      varying vec2 vLocal; varying float vU; varying vec3 vW; varying vec3 vN;
      void main(){
        float n = noise3(vec3(vLocal * 5.5, uSeed * 7.0));
        float level = smoothstep(0.18, 0.9, vU);
        if (n < level) discard;
        float edge = 1.0 - smoothstep(0.30, 0.5, max(abs(vLocal.x), abs(vLocal.y)));
        vec3 N = normalize(vN);
        if (!gl_FrontFacing) N = -N;
        vec3 V = normalize(uCam - vW);
        float fres = pow(1.0 - abs(dot(N, V)), 2.0);
        vec3 col = vec3(0.35, 0.55, 0.62) * 0.4 + vec3(0.8, 0.95, 1.0) * fres * 0.9;
        col += vec3(1.0) * pow(max(dot(N, normalize(normalize(vec3(0.485, 0.727, 0.727)) + V)), 0.0), 120.0);
        float a = 0.42 * edge * (1.0 - vU * 0.55) * (0.35 + 0.65 * fres);
        if (a < 0.004) discard;
        gl_FragColor = vec4(col, a);
        #include <tonemapping_fragment>
        #include <encodings_fragment>
      }
    `
  });
  const mesh = new THREE.Mesh(sheetGeo, mat);
  mesh.renderOrder = 4;
  mesh.frustumCulled = false;
  scene.add(mesh);
  sheetMats.push(mat);
});

/* ============================================================
   renderAt(simTime) — pure, deterministic scene evaluation
   ============================================================ */
function smooth(a, b, x) {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
}
function renderAt(t) {
  latexUniforms.uTime.value = t;
  waterUniforms.uTime.value = t;
  dropletUniforms.uTime.value = t;
  shredUniforms.uTime.value = t;
  tunnelUniforms.uTime.value = t;
  for (let i = 0; i < sheetMats.length; i++) sheetMats[i].uniforms.uTime.value = t;

  // bullet
  const tx = tipX(t);
  bullet.position.set(tx, 0.15, 0);
  bullet.rotation.x = -t * 55;
  const wob = (t > T_PUNCT && t < T_EXIT + 0.6)
    ? 0.04 * Math.sin((t - T_PUNCT) * 9) * Math.exp(-(t - T_PUNCT) * 1.1) : 0;
  bullet.rotation.z = wob;
  bullet.rotation.y = wob * 0.6;
  bulletMat.roughness = 0.32 - 0.16 * smooth(1.13, 1.5, t) * (1 - smooth(5.2, 6.2, t));

  // tether sway + knot recoil
  const pre = 0.012 * Math.sin(t * 1.1);
  const bt = Math.max(0, t - T_PUNCT);
  const recoil = 0.045 * Math.exp(-bt * 2.0) * Math.sin(bt * 24) * (t > T_PUNCT ? 1 : 0);
  tether.rotation.z = pre + recoil;
  knot.position.y = 1.44 + 0.04 * Math.exp(-bt * 3.0) * Math.sin(bt * 30) * (t > T_PUNCT ? 1 : 0);
  knot.position.x = -(pre + recoil) * 0.1;

  // impact flashes
  flashEntry.intensity = t > T_PUNCT ? 3.2 * Math.exp(-(t - T_PUNCT) * 8) : 0;
  flashExit.intensity = t > T_EXIT ? 2.6 * Math.exp(-(t - T_EXIT) * 7) : 0;

  // cavitation tunnel
  const tAlpha = smooth(2.35, 2.6, t) * (1 - smooth(3.95, 4.35, t));
  if (tAlpha > 0.002 && tx < 0.85) {
    const x0 = 0.88, x1 = tx - 0.06;
    const L = Math.max(0.05, x0 - x1);
    const R = (0.10 + 0.10 * smooth(2.4, 3.1, t)) * (1 - 0.75 * smooth(3.9, 4.3, t));
    tunnel.visible = true;
    tunnel.position.set((x0 + x1) / 2, 0.12, 0);
    tunnel.scale.set(L, Math.max(0.02, R), Math.max(0.02, R));
    tunnelUniforms.uAlpha.value = tAlpha * 0.85;
  } else {
    tunnel.visible = false;
  }

  // shock rings
  const ae = t - T_PUNCT;
  if (ae > 0 && ae < 0.85) {
    ringEntry.visible = true;
    const s = 0.15 + ae * 3.4;
    ringEntry.scale.set(s, s, 1);
    ringEntry.material.uniforms.uAlpha.value = 0.85 * Math.exp(-ae * 6);
  } else ringEntry.visible = false;
  const ax = t - T_EXIT;
  if (ax > 0 && ax < 0.85) {
    ringExit.visible = true;
    const s = 0.15 + ax * 3.8;
    ringExit.scale.set(s, s, 1);
    ringExit.material.uniforms.uAlpha.value = 0.9 * Math.exp(-ax * 6);
  } else ringExit.visible = false;

  renderer.render(scene, camera);
}

/* ============================================================
   Resize
   ============================================================ */
function updatePixelScale() {
  const h = renderer.domElement.height; // device px
  const s = h / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov) / 2));
  dropletUniforms.uPixelScale.value = s;
  shredUniforms.uPixelScale.value = s;
}
function onResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight, false);
  updatePixelScale();
}
window.addEventListener('resize', onResize);
updatePixelScale();

/* ============================================================
   Playback state machine:
   COUNTDOWN -> PLAYING -> ENDED, with PAUSED and REFIRE_HOLD
   ============================================================ */
const countdownEl = document.getElementById('countdown');
const scrubber = document.getElementById('scrubber');
const btnToggle = document.getElementById('btn-toggle');
const btnRefire = document.getElementById('btn-refire');
const iconPause = document.getElementById('icon-pause');
const iconPlay = document.getElementById('icon-play');
const speedPills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));

const COUNTDOWN = 'COUNTDOWN', PLAYING = 'PLAYING', PAUSED = 'PAUSED',
      REFIRE_HOLD = 'REFIRE_HOLD', ENDED = 'ENDED';

let state = COUNTDOWN;
let simTime = 0.000;
let playbackSpeed = 1.0;
let countdownElapsed = 0;
let holdElapsed = 0;

function hideCountdown() {
  countdownEl.style.display = 'none';
  countdownEl.textContent = '';
}
function showCountdown(n) {
  countdownEl.style.display = 'block';
  countdownEl.textContent = String(n);
}
function setIcons(playing) {
  iconPause.style.display = playing ? '' : 'none';
  iconPlay.style.display = playing ? 'none' : '';
  btnToggle.setAttribute('aria-label', playing ? 'Pause' : 'Play');
}
function enterPlaying() {
  hideCountdown();
  state = PLAYING;
  setIcons(true);
}

btnToggle.addEventListener('click', function () {
  if (state === PLAYING) {
    state = PAUSED;
    setIcons(false);
  } else if (state === COUNTDOWN || state === REFIRE_HOLD) {
    hideCountdown();
    simTime = 0.000;
    scrubber.value = '0';
    state = PAUSED;
    setIcons(false);
    renderAt(simTime);
  } else if (state === PAUSED) {
    state = PLAYING;
    setIcons(true);
  } else if (state === ENDED) {
    simTime = 0.000;
    scrubber.value = '0.000';
    hideCountdown();
    state = PLAYING;
    setIcons(true);
    renderAt(simTime);
  }
});

btnRefire.addEventListener('click', function () {
  hideCountdown();
  simTime = 0.000;
  scrubber.value = '0';
  holdElapsed = 0;
  state = REFIRE_HOLD;
  setIcons(true);
  renderAt(simTime);
});

scrubber.addEventListener('input', function () {
  if (state === COUNTDOWN || state === REFIRE_HOLD) hideCountdown();
  simTime = parseFloat(scrubber.value);
  state = PAUSED;
  setIcons(false);
  renderAt(simTime);
});

speedPills.forEach(function (pill) {
  pill.addEventListener('click', function () {
    playbackSpeed = parseFloat(pill.dataset.speed);
    speedPills.forEach(function (p) {
      const active = p === pill;
      p.classList.toggle('is-active', active);
      p.setAttribute('aria-checked', active ? 'true' : 'false');
    });
  });
});

/* Initial resting scene at simTime = 0 */
renderAt(0);

/* Main loop — countdown / hold timers use wall-clock dt;
   simulation advance uses dt clamped to 0.1 s. */
let started = false;
let prev = null;
function frame(now) {
  requestAnimationFrame(frame);
  if (!started) {
    started = true;      // first rAF after the resting scene rendered
    prev = now;
    countdownElapsed = 0;
  }
  let raw = (now - prev) / 1000;
  prev = now;
  if (raw < 0) raw = 0;
  const dt = Math.min(raw, 0.1);

  if (state === COUNTDOWN) {
    countdownElapsed += raw;
    if (countdownElapsed >= 3.000) {
      enterPlaying();
    } else {
      showCountdown(Math.min(3, Math.ceil(3.000 - countdownElapsed)));
    }
  } else if (state === REFIRE_HOLD) {
    holdElapsed += raw;
    if (holdElapsed >= 1.000) enterPlaying();
  } else if (state === PLAYING) {
    simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
    scrubber.value = simTime.toFixed(3);
    if (simTime >= DURATION) {
      simTime = DURATION;
      scrubber.value = DURATION.toFixed(3);
      state = ENDED;
      setIcons(false);
    }
  }
  renderAt(simTime);
}
requestAnimationFrame(frame);

})();
</script>
</body>
</html>
"}

