// ---- Tests ----
// SRC is injected between prefix and suffix by the build step.

function scenarioA() {
  var env = setup();
  (0, eval)(SRC);
  var E = env.elements;

  assert(env.renderCount >= 1, 'A: initial resting scene rendered');
  assert(E['countdown'].style.display !== 'none', 'A: countdown visible at launch');
  assert(E['countdown'].textContent === '3', 'A: countdown shows 3 initially');
  assert(E['scrubber'].value === '0', 'A: scrubber stays 0 initially');

  pumpFor(env, 500, 16.7);
  assert(E['countdown'].textContent === '3', 'A: countdown 3 during [0,1)');
  assert(E['countdown'].style.display === 'block', 'A: countdown display block');
  assert(E['scrubber'].value === '0', 'A: scrubber 0 during countdown');
  pumpFor(env, 1000, 16.7);
  assert(E['countdown'].textContent === '2', 'A: countdown 2 during [1,2)');
  pumpFor(env, 1000, 16.7);
  assert(E['countdown'].textContent === '1', 'A: countdown 1 during [2,3)');
  assert(E['scrubber'].value === '0', 'A: scrubber still 0 before launch');
  pumpFor(env, 600, 16.7);
  assert(E['countdown'].style.display === 'none', 'A: countdown hidden after 3s');
  assert(E['countdown'].textContent === '', 'A: countdown text cleared');
  assert(parseFloat(E['scrubber'].value) > 0, 'A: PLAYING advances simTime');
  assert(E['btn-toggle'].attrs['aria-label'] === 'Pause', 'A: aria Pause while playing');
  assert(E['icon-pause'].style.display === '' && E['icon-play'].style.display === 'none', 'A: pause icon while playing');

  pumpFor(env, 8200, 100);
  assert(E['scrubber'].value === '8.000', 'A: scrubber clamps to 8.000, got ' + E['scrubber'].value);
  assert(E['btn-toggle'].attrs['aria-label'] === 'Play', 'A: ENDED aria Play');
  assert(E['icon-play'].style.display === '' && E['icon-pause'].style.display === 'none', 'A: ENDED shows play icon');
  pumpFor(env, 500, 100);
  assert(E['scrubber'].value === '8.000', 'A: ENDED holds final frame');

  click(E['btn-toggle']); // ENDED -> reset + PLAYING
  assert(E['scrubber'].value === '0.000', 'A: ENDED toggle resets to 0.000');
  assert(E['btn-toggle'].attrs['aria-label'] === 'Pause', 'A: ENDED toggle goes straight to PLAYING');
  assert(E['countdown'].style.display === 'none', 'A: no countdown on ENDED toggle');
  pumpFor(env, 300, 100);
  assert(parseFloat(E['scrubber'].value) > 0.2, 'A: playback resumes after ENDED toggle');

  click(E['btn-toggle']); // -> PAUSED
  assert(E['btn-toggle'].attrs['aria-label'] === 'Play', 'A: pause toggle aria Play');
  var frozen = E['scrubber'].value;
  pumpFor(env, 500, 100);
  assert(E['scrubber'].value === frozen, 'A: PAUSED freezes simTime');

  click(E['btn-refire']); // -> REFIRE_HOLD
  assert(E['scrubber'].value === '0', 'A: refire resets scrubber to 0');
  assert(E['countdown'].style.display === 'none' && E['countdown'].textContent === '', 'A: refire hides countdown');
  assert(E['btn-toggle'].attrs['aria-label'] === 'Pause', 'A: refire shows pause icon');
  assert(E['icon-pause'].style.display === '', 'A: refire icon-pause visible');
  pumpFor(env, 900, 100);
  assert(E['scrubber'].value === '0', 'A: REFIRE_HOLD silent for first 0.9s');
  assert(E['countdown'].style.display === 'none', 'A: countdown stays hidden during hold');
  pumpFor(env, 250, 100);
  assert(parseFloat(E['scrubber'].value) > 0, 'A: REFIRE_HOLD auto-plays after 1.0s');

  scrubTo(env, '2.500');
  assert(E['btn-toggle'].attrs['aria-label'] === 'Play', 'A: scrubbing pauses');
  pumpFor(env, 400, 100);
  assert(E['scrubber'].value === '2.500', 'A: scrubbed time frozen');

  // determinism of uniform state at identical simTime
  var snap1 = uTimes(env);
  scrubTo(env, '6.183');
  scrubTo(env, '2.500');
  var snap2 = uTimes(env);
  assert(snap1.length >= 15, 'A: expected >=15 time-driven materials, got ' + snap1.length);
  assert(JSON.stringify(snap1) === JSON.stringify(snap2), 'A: scrub back/forth yields identical state');
  scrubTo(env, '0');
  assert(uTimes(env).every(function (v) { return v === 0; }), 'A: reset returns all uniforms to t=0');

  // speed selection + persistence across refire and scrub
  click(env.pills[3]); // 2.0x
  var checked = env.pills.map(function (p) { return p.attrs['aria-checked']; });
  assert(JSON.stringify(checked) === JSON.stringify(['false', 'false', 'false', 'true']), 'A: exclusive aria-checked');
  assert(env.pills[3].classList.contains('is-active') && !env.pills[2].classList.contains('is-active'), 'A: is-active moved');
  click(E['btn-refire']);
  pumpFor(env, 1100, 100); // 1.0s hold + 0.1s at 2x
  var v2 = parseFloat(E['scrubber'].value);
  assert(v2 > 0.1 && v2 < 0.45, 'A: 2x speed after refire, got ' + v2);
  scrubTo(env, '4.000');
  click(E['btn-toggle']);
  pumpFor(env, 500, 100); // +1.0s at 2x
  var v4 = parseFloat(E['scrubber'].value);
  assert(Math.abs(v4 - 5.0) < 0.15, 'A: speed persists across scrub, got ' + v4);

  // particle budgets
  var seen = [], counts = [];
  env.geoms.forEach(function (g) {
    if (g.attrs.aBirth && seen.indexOf(g) === -1) { seen.push(g); counts.push(g.attrs.aBirth.array.length); }
  });
  counts.sort(function (a, b) { return a - b; });
  assert(counts.length === 2, 'A: two particle systems, got ' + counts.length);
  assert(counts[1] >= 2000 && counts[1] <= 6000, 'A: main particle count in [2000,6000], got ' + counts[1]);
  assert(counts[0] === 160, 'A: 160 latex shreds, got ' + counts[0]);

  assert(env.resizeHandlers.length === 1, 'A: resize handler registered');
  env.resizeHandlers[0]();
  assert(true, 'A: resize runs without error');
}

function scenarioB() {
  var env = setup();
  (0, eval)(SRC);
  var E = env.elements;

  pumpFor(env, 500, 16.7);
  assert(E['countdown'].textContent === '3', 'B: countdown running');
  click(E['btn-toggle']); // cancel countdown -> PAUSED
  assert(E['countdown'].style.display === 'none', 'B: toggle cancels countdown');
  assert(E['scrubber'].value === '0', 'B: simTime kept at 0');
  assert(E['btn-toggle'].attrs['aria-label'] === 'Play', 'B: paused after countdown cancel');
  pumpFor(env, 3500, 100);
