import re
from html.parser import HTMLParser

html = open('index.html').read()
errors = []

# --- 1. body structure: only canonical elements ---
class BodyParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_body = False
        self.body_children = []
        self.stack = []
        self.ids = []
    def handle_starttag(self, tag, attrs):
        d = dict(attrs)
        if 'id' in d: self.ids.append(d['id'])
        if tag == 'body': self.in_body = True; return
        if self.in_body and len(self.stack) == 0:
            self.body_children.append((tag, d.get('id')))
        if tag not in ('input', 'meta', 'link', 'br', 'img', 'path', 'rect'):
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag == 'body': self.in_body = False; return
        if self.stack and self.stack[-1] == tag: self.stack.pop()

p = BodyParser()
p.feed(html)
expected = [('canvas', 'stage'), ('div', 'countdown'), ('div', 'dock'), ('script', None), ('script', None)]
if p.body_children != expected:
    errors.append(f'body children mismatch: {p.body_children}')

required_ids = ['stage', 'countdown', 'dock', 'btn-refire', 'btn-toggle', 'icon-pause', 'icon-play', 'speed-group', 'scrubber']
for rid in required_ids:
    if rid not in p.ids: errors.append(f'missing id {rid}')
if p.ids.count('stage') != 1: errors.append('stage id not unique')

# --- 2. canonical dock markup (normalized whitespace) ---
def norm(s):
    s = re.sub(r'>\s+<', '><', s.strip())
    s = re.sub(r'\s+', ' ', s)
    return s

canonical_dock = '''<div id="dock" role="toolbar" aria-label="Simulation Controls">
  <button id="btn-refire" type="button" aria-label="Re-fire" title="Re-fire">
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
      <path d="M21.5 2v6h-6M21.34 15.57a10 10 0 1 1-.57-8.38l5.67-5.19"/>
    </svg>
    <span>Re-fire</span>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <button id="btn-toggle" type="button" aria-label="Pause" title="Play / Pause">
    <svg id="icon-pause" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true">
      <rect x="6" y="4" width="4" height="16" rx="1"/>
      <rect x="14" y="4" width="4" height="16" rx="1"/>
    </svg>
    <svg id="icon-play" viewBox="0 0 24 24" width="14" height="14" fill="currentColor" aria-hidden="true" style="display:none;">
      <path d="M8 5v14l11-7z"/>
    </svg>
  </button>
  <span class="dock-sep" aria-hidden="true"></span>
  <div id="speed-group" role="radiogroup" aria-label="Playback Speed">
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.25">0.25×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="0.5">0.5×</button>
    <button class="speed-pill is-active" type="button" role="radio" aria-checked="true" data-speed="1.0">1.0×</button>
    <button class="speed-pill" type="button" role="radio" aria-checked="false" data-speed="2.0">2.0×</button>
  </div>
  <span class="dock-sep" aria-hidden="true"></span>
  <input id="scrubber" type="range" min="0" max="8.000" step="0.001" value="0" aria-label="Timeline Scrubber">
</div>'''
m = re.search(r'<div id="dock".*?</div>\s*(?=<script)', html, re.S)
if not m:
    errors.append('dock block not found')
else:
    # dock contains nested div (speed-group); find matching close by depth
    start = html.index('<div id="dock"')
    depth = 0; i = start; end = None
    for mm in re.finditer(r'<div\b|</div>', html[start:]):
        if mm.group(0) == '</div>':
            depth -= 1
            if depth == 0: end = start + mm.end(); break
        else:
            depth += 1
    dock_html = html[start:end]
    if norm(dock_html) != norm(canonical_dock):
        errors.append('dock markup differs from canonical')

if norm('<div id="countdown" aria-hidden="true">3</div>') not in norm(html):
    errors.append('countdown element differs from canonical')
if '<canvas id="stage"></canvas>' not in html:
    errors.append('stage canvas differs from canonical')

# --- 3. mandatory CSS verbatim blocks ---
style = re.search(r'<style>(.*?)</style>', html, re.S).group(1)
css_blocks = [
'''*, *::before, *::after {
  box-sizing: border-box;
}''',
'''html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: radial-gradient(circle at center, #161922 0%, #090a0f 100%);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  -webkit-user-select: none;
  user-select: none;
}''',
'''#stage {
  display: block;
  width: 100vw;
  height: 100vh;
}''',
'''#countdown {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 50;
  pointer-events: none;
  font-size: 96px;
  font-weight: 700;
  line-height: 1;
  color: rgba(255, 255, 255, 0.35);
  font-variant-numeric: tabular-nums;
}''',
'''#dock {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 100;
  width: 536px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 0 14px;
  background: rgba(15, 17, 23, 0.78);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.35);
}''',
'''#dock button {
  font-family: inherit;
  line-height: 1;
  margin: 0;
  flex-shrink: 0;
  white-space: nowrap;
  appearance: none;
  -webkit-appearance: none;
}''',
'''.dock-sep {
  width: 1px;
  height: 18px;
  flex-shrink: 0;
  background: rgba(255, 255, 255, 0.12);
}''',
'''#btn-refire {
  width: 78px;
  height: 28px;
  padding: 0 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
  color: #ffffff;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
}''',
'''#btn-refire:hover {
  background: rgba(255, 255, 255, 0.16);
}''',
'''#btn-toggle {
  width: 28px;
  height: 28px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 9999px;
  color: #ffffff;
  cursor: pointer;
}''',
'''#btn-toggle:hover {
  background: rgba(255, 255, 255, 0.16);
}''',
'''#speed-group {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}''',
'''.speed-pill {
  width: 42px;
  height: 24px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 9999px;
  color: rgba(255, 255, 255, 0.6);
  font-size: 11px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
}''',
'''.speed-pill:hover {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.06);
}''',
'''.speed-pill.is-active {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.18);
  border-color: rgba(255, 255, 255, 0.2);
}''',
'''#scrubber {
  width: 157px;
  height: 4px;
  margin: 0;
  padding: 0;
  flex-shrink: 0;
  appearance: none;
  -webkit-appearance: none;
  background: rgba(255, 255, 255, 0.22);
  border-radius: 9999px;
  outline: none;
  cursor: pointer;
}''',
'''#scrubber::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #ffffff;
  border: none;
  cursor: pointer;
}''',
'''#scrubber::-moz-range-thumb {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #ffffff;
  border: none;
  cursor: pointer;
}''',
]
for i, block in enumerate(css_blocks):
    if block not in style:
        errors.append(f'CSS block {i} not verbatim: {block.splitlines()[0]}')

# --- 4. mandatory JS lines ---
js_lines = [
    'const DURATION = 8.000;',
    "new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: true })",
    'renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));',
    'renderer.setSize(window.innerWidth, window.innerHeight, false);',
    'renderer.outputEncoding = THREE.sRGBEncoding;',
    'mulberry32(42)',
    'https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js',
]
for line in js_lines:
    if line not in html:
        errors.append(f'mandatory line missing: {line}')

